/* ---------------------------- pills ---------------------------- */
function pillClass(estado) {
  const verde = ['Activo','Publicado'];
  const rojo = ['Inactivo'];
  const ambar = ['Pendiente','Borrador'];
  const azul = ['En revisión'];
  const gris = ['Archivado'];
  if (verde.includes(estado)) return 'pill-verde';
  if (rojo.includes(estado)) return 'pill-clay';
  if (ambar.includes(estado)) return 'pill-ambar';
  if (azul.includes(estado)) return 'pill-azul';
  if (gris.includes(estado)) return 'pill-gris';
  return 'pill-gris';
}
function pill(estado) { return '<span class="pill ' + pillClass(estado) + '">' + esc(estado) + '</span>'; }
function rolePill(rol) {
  const color = ROLE_COLOR[rol] || 'var(--ink-soft)';
  return '<span class="flex items-center gap-6" style="font-size:12.5px;font-weight:600;color:'+color+'"><span style="width:7px;height:7px;border-radius:50%;background:'+color+';display:inline-block"></span>' + esc(ROLE_LABEL[rol] || rol) + '</span>';
}

/* ---------------------------- selector con búsqueda (SearchableSelect) ---------------------------- */
function searchableSelectHTML(id, placeholder) {
  return '<div class="rte-dropdown" style="position:relative">' +
    '<input type="text" id="'+id+'-search" placeholder="'+esc(placeholder||'Buscar...')+'" autocomplete="off" oninput="ssFiltrar(\''+id+'\')" onfocus="ssFiltrar(\''+id+'\')">' +
    '<input type="hidden" id="'+id+'">' +
    '<div class="rte-menu" id="'+id+'-sugerencias" style="width:100%;max-width:none;max-height:220px;overflow-y:auto"></div></div>';
}
let SS_OPTIONS = {};
function ssSetOptions(id, options) { SS_OPTIONS[id] = options; }
function ssFiltrar(id) {
  const q = document.getElementById(id+'-search').value.trim().toLowerCase();
  const opciones = (SS_OPTIONS[id]||[]).filter(o => o.label.toLowerCase().includes(q));
  const cont = document.getElementById(id+'-sugerencias');
  if (opciones.length === 0) { cont.innerHTML = '<div class="rte-menu-item muted">Sin resultados</div>'; cont.classList.add('abierto'); return; }
  cont.innerHTML = opciones.map(o => '<div class="rte-menu-item" onmousedown="event.preventDefault()" onclick="ssSeleccionar(\''+id+'\',\''+esc(o.value).replace(/'/g,"\\'")+'\',\''+esc(o.label).replace(/'/g,"\\'")+'\')">'+esc(o.label)+'</div>').join('');
  cont.classList.add('abierto');
}
function ssSeleccionar(id, value, label) {
  document.getElementById(id+'-search').value = label;
  document.getElementById(id).value = value;
  document.getElementById(id+'-sugerencias').classList.remove('abierto');
}
function ssReset(id) { document.getElementById(id+'-search').value=''; document.getElementById(id).value=''; }

